import base64, gzip, json
import pandas as pd
import streamlit as st

st.set_page_config(page_title="Beauty Review Intelligence", page_icon="💄", layout="wide")
PACKED_DATA = ""

@st.cache_data(show_spinner="Loading the embedded product and review data…")
def load_data():
    raw = json.loads(gzip.decompress(base64.b64decode(PACKED_DATA)))
    return raw, pd.DataFrame(raw["products"]), pd.DataFrame(raw["review_examples"])

def action(p):
    if p.avg_rating < 3 or p.negative_rate >= .45: return "Investigate"
    if p.avg_rating < 3.8 or p.negative_rate >= .30: return "Review"
    if p.avg_rating >= 4.5 and p.negative_rate < .15: return "Strong"
    return "Monitor"

def short(n):
    return f"{n/1e6:.1f}M" if n >= 1e6 else f"{n/1e3:.1f}K" if n >= 1e3 else f"{n:,.0f}"

raw, products, examples = load_data()
st.markdown("""<style>
.block-container{max-width:1440px;padding-top:1.2rem}
[data-testid="stAppViewContainer"]{background:#f2f5f9}
div[data-testid="stMetric"]{background:white;border:1px solid #dce5ef;padding:14px 16px;border-radius:14px}
</style>""", unsafe_allow_html=True)
left, right = st.columns([4,1])
with left:
    st.title("💄 Beauty Review Intelligence")
    st.caption("Customer satisfaction · Product performance · Voice of customer")
with right: st.markdown("**AMAZON BEAUTY** · CLEANED DATASET")
meta = raw["metadata"]
st.info(f"**Analysis scope:** {meta['total_review_rows']:,} cleaned review rows · {meta['valid_rating_reviews']:,} valid ratings · {meta['product_count']:,} products. Negative review = 1–2 stars. Review volume reflects feedback, not sales.")

st.subheader("Filters")
a,b,c=st.columns([1.5,1,1]); d,e,f=st.columns(3)
with a: query=st.text_input("Product or brand",placeholder="Search products, brands, IDs…")
with b:
    brand_options=sorted(products.brand.dropna().astype(str).unique(),key=str.casefold)
    brand=st.selectbox("Brand / store",["All brands",*brand_options[:1500]])
with c: price=st.selectbox("Price range",["All / unavailable","Under $25","$25–$50","$50–$100","$100+","Price unavailable"])
with d: satisfaction=st.selectbox("Satisfaction",["All ratings","Strong · 4.5+","Moderate · 3.5–4.49","At risk · below 3.5","High negative rate · 30%+"])
with e:
    issue_options=sorted(products.main_issue.dropna().astype(str).unique())
    issue=st.selectbox("Main issue",["All issue topics",*issue_options])
with f: min_reviews=st.selectbox("Minimum reviews",[0,25,100,250,500],format_func=lambda n:"All products" if n==0 else f"{n}+")

view=products
if query.strip():
    q=query.strip().casefold()
    mask=(view.product.fillna("").str.casefold().str.contains(q,regex=False)|view.brand.fillna("").str.casefold().str.contains(q,regex=False)|view.product_id.fillna("").str.casefold().str.contains(q,regex=False))
    view=view[mask]
if brand!="All brands": view=view[view.brand==brand]
if issue!="All issue topics": view=view[view.main_issue==issue]
if min_reviews: view=view[view.review_count>=min_reviews]
if price=="Price unavailable": view=view[view.price.isna()]
elif price=="Under $25": view=view[view.price.notna()&(view.price<25)]
elif price=="$25–$50": view=view[view.price.ge(25)&view.price.lt(50)]
elif price=="$50–$100": view=view[view.price.ge(50)&view.price.lt(100)]
elif price=="$100+": view=view[view.price.ge(100)]
if satisfaction=="Strong · 4.5+": view=view[view.avg_rating>=4.5]
elif satisfaction=="Moderate · 3.5–4.49": view=view[view.avg_rating.ge(3.5)&view.avg_rating.lt(4.5)]
elif satisfaction=="At risk · below 3.5": view=view[view.avg_rating<3.5]
elif satisfaction=="High negative rate · 30%+": view=view[view.negative_rate>=.30]

count=len(view); reviews=int(view.review_count.sum()) if count else 0
rating=(view.avg_rating*view.review_count).sum()/reviews if reviews else None
negative=(view.negative_rate*view.review_count).sum()/reviews if reviews else None
verified=(view.verified_rate.fillna(0)*view.review_count).sum()/reviews if reviews else None
st.caption(f"{count:,} products match · {reviews:,} reviews represented")
k=st.columns(5)
k[0].metric("Products in view",f"{count:,}"); k[1].metric("Review volume",short(reviews))
k[2].metric("Average rating",f"{rating:.2f}" if rating is not None else "—")
k[3].metric("Negative review rate",f"{negative:.1%}" if negative is not None else "—")
k[4].metric("Verified purchase rate",f"{verified:.1%}" if verified is not None else "—")

left,right=st.columns([2,1])
with left:
    st.subheader("Product performance matrix")
    st.caption("Each point is a product · rating vs. review volume · color shows negative-review rate")
    if count:
        plot=view.nlargest(1500,"review_count").copy()
        plot["Negative review rate"]=pd.cut(plot.negative_rate,[-.001,.15,.30,1.01],labels=["Low","Medium","High"])
        st.scatter_chart(plot,x="review_count",y="avg_rating",color="Negative review rate",size="review_count",height=340)
    else: st.info("No products match the current filters.")
    st.caption("Up to 1,500 products are plotted; KPIs and table use all matches. Prioritize high-volume products with low ratings.")
with right:
    st.subheader("Action queue"); st.caption("Rule-based signals in the current filtered view")
    urgent=int(((view.review_count>=20)&((view.avg_rating<3)|(view.negative_rate>=.45))).sum())
    review_n=int(((view.review_count>=20)&(view.avg_rating>=3)&(view.avg_rating<3.8)).sum())
    strong=int(((view.review_count>=20)&(view.avg_rating>=4.5)&(view.negative_rate<.15)).sum())
    for title,desc,n in [("Immediate attention","High negatives or weak rating",urgent),("Needs review","Moderate dissatisfaction",review_n),("Strong products","High rating, low negative share",strong),("Monitor","No priority threshold triggered",max(0,count-urgent-review_n-strong))]:
        st.markdown(f"**{title} · {n:,}**  \n{desc}")
    st.caption("Screening signals, not proof of product defects.")

x,y,z=st.columns([1.2,1,1])
with x:
    st.subheader("Rating & feedback trend"); st.caption("Annual average rating and review volume · full dataset")
    yearly=pd.DataFrame(raw["yearly"]); yearly=yearly[yearly.year>=2010].set_index("year")
    st.line_chart(yearly[["avg_rating"]],color="#10a98c",height=220)
    st.bar_chart(yearly[["reviews"]],color="#9ac4e1",height=150)
with y:
    st.subheader("Top negative-review issues"); st.caption("Keyword themes in 1–2 star reviews")
    issues=pd.DataFrame(raw["issues"]); issues=issues[issues.issue!="Other"].head(7).set_index("issue")
    st.bar_chart(issues[["reviews"]],color="#e45d58",height=300)
    st.caption("Rule-based categories; each review is assigned to its first matching category.")
with z:
    st.subheader("Rating distribution"); st.caption("Review mix across the full dataset")
    dist=pd.DataFrame(raw["rating_distribution"]).sort_values("rating",ascending=False).set_index("rating")
    st.bar_chart(dist[["reviews"]],color="#4b9bd8",height=300)
    st.caption("Valid 1–5 star ratings.")

st.subheader("Product action table")
st.caption("Select a product to inspect sampled feedback and product-level metrics.")
sort=st.selectbox("Sort products",["Action priority","Review volume","Lowest rating","Highest rating","Negative rate"],label_visibility="collapsed")
show=view.copy(); show["Action"]=show.apply(action,axis=1)
if sort=="Review volume": show=show.sort_values("review_count",ascending=False)
elif sort=="Lowest rating": show=show.sort_values("avg_rating")
elif sort=="Highest rating": show=show.sort_values("avg_rating",ascending=False)
elif sort=="Negative rate": show=show.sort_values("negative_rate",ascending=False)
else:
    show["_priority"]=show.apply(lambda p: {"Investigate":4,"Review":3,"Monitor":2,"Strong":1}[p.Action]*1_000_000_000+p.review_count,axis=1)
    show=show.sort_values("_priority",ascending=False)
page_size=10; pages=max(1,(len(show)+page_size-1)//page_size)
if "product_page" not in st.session_state: st.session_state.product_page=0
st.session_state.product_page=min(st.session_state.product_page,pages-1)
p1,p2,p3=st.columns([1,5,1])
with p1:
    if st.button("← Previous",disabled=st.session_state.product_page==0): st.session_state.product_page-=1; st.rerun()
with p3:
    if st.button("Next →",disabled=st.session_state.product_page>=pages-1): st.session_state.product_page+=1; st.rerun()
start=st.session_state.product_page*page_size; page_data=show.iloc[start:start+page_size].copy()
with p2: st.caption(f"Showing {start+1:,}–{min(start+page_size,len(show)):,} of {len(show):,} products" if len(show) else "No matching products")
if len(page_data):
    table=page_data[["product","brand","price","avg_rating","review_count","negative_rate","verified_rate","rating_2023","rating_2022","main_issue","Action"]].copy()
    table["price"]=table.price.map(lambda v:"—" if pd.isna(v) else f"${v:,.2f}")
    table["negative_rate"]=table.negative_rate.map(lambda v:f"{v:.1%}")
    table["verified_rate"]=table.verified_rate.map(lambda v:"—" if pd.isna(v) else f"{v:.1%}")
    table=table.rename(columns={"product":"Product","brand":"Brand","price":"Price","avg_rating":"Avg rating","review_count":"Reviews","negative_rate":"Negative %","verified_rate":"Verified %","rating_2023":"2023 rating","rating_2022":"2022 rating","main_issue":"Main issue"})
    st.dataframe(table,hide_index=True,use_container_width=True)
    ids=page_data.product_id.tolist()
    selected_id=st.selectbox("Product details",ids,format_func=lambda pid:f"{page_data.loc[page_data.product_id==pid,'product'].iloc[0]} · {pid}")
    p=products.loc[products.product_id==selected_id].iloc[0]
    st.markdown(f"#### {p['product']}  \n{p['brand']} · {selected_id}")
    ds=st.columns(4)
    ds[0].metric("Average rating",f"{p.avg_rating:.2f} ★"); ds[1].metric("Reviews",f"{p.review_count:,}")
    ds[2].metric("Negative rate",f"{p.negative_rate:.1%}"); ds[3].metric("Verified rate","—" if pd.isna(p.verified_rate) else f"{p.verified_rate:.1%}")
    feedback=examples[examples.product_id==selected_id]
    st.markdown("**Helpful negative feedback**")
    if feedback.empty: st.caption("No sampled negative-review excerpts are available for this product.")
    for _,r in feedback.iterrows():
        with st.container(border=True):
            st.markdown(f"**{r.review_title or 'Customer review'} · {r.rating:g} ★**")
            st.write(r.review_text or "")
            verified_label="Verified purchase" if r.verified is True else "Unverified purchase" if r.verified is False else "Verification unavailable"
            st.caption(f"{int(r.helpful_votes or 0):,} helpful votes · {verified_label}")
    st.caption("Sampled high-helpfulness negative feedback, capped at 3,000 excerpts overall.")
st.divider()
st.caption("Source: Amazon Reviews 2023 Beauty cleaned Parquet. All 694,253 source review rows were processed; product-level views cover 112,565 products. Review volume reflects customer feedback, not sales.")
